import {THREE,mesh,box,canvasTexture,getCrestImage} from './kit.js';
export function buildArenaScreens(bowl,batch,{dark,steel}){
 const textures=[false,true].map(match=>canvasTexture(1536,864,c=>{
  const gradient=c.createLinearGradient(0,0,1536,864);gradient.addColorStop(0,'#1c2831');gradient.addColorStop(1,'#0d171e');c.fillStyle=gradient;c.fillRect(0,0,1536,864);c.fillStyle='#b01d35';c.fillRect(0,0,1536,16);c.textAlign='center';c.fillStyle='#b5c1c7';c.font='600 28px Arial';c.fillText(match?'PRE-MATCH · EXHIBITION':'MÜNCHEN · HOME OF FC BAYERN',768,96);
  if(match){c.drawImage(getCrestImage('home'),190,200,205,205);c.drawImage(getCrestImage('away'),1140,200,205,205);c.fillStyle='#f3f1e9';c.font='600 62px Arial';c.fillText('FC BAYERN',292,503);c.fillText('DORTMUND',1244,503);c.font='600 190px Arial';c.fillText('0 : 0',768,403);c.font='400 36px Arial';c.fillStyle='#aab9bd';c.fillText('11  vs  11',768,512);c.fillStyle='#b01d35';c.fillRect(190,591,205,7);c.fillStyle='#ddc132';c.fillRect(1140,591,205,7);}
  else{c.drawImage(getCrestImage('home'),632,175,272,272);c.fillStyle='#f1efe6';c.font='600 90px Arial';c.fillText('ALLIANZ ARENA',768,596);}
  c.fillStyle='#b7c4c8';c.font='500 32px Arial';c.fillText(match?'FC BAYERN MÜNCHEN × BORUSSIA DORTMUND':'WILLKOMMEN · MIA SAN MIA',768,756);
 }));
 const material=new THREE.MeshBasicMaterial({map:textures[0],toneMapped:false});for(const z of[-78,78]){const group=new THREE.Group();group.name='Arena LED scoreboard';group.position.set(0,42.5,z);if(z>0)group.rotation.y=Math.PI;bowl.add(group);box(group,19.4,11.3,.55,0,0,0,dark);mesh(new THREE.PlaneGeometry(18.8,10.6),material,group,0,0,.3);const rear=mesh(new THREE.PlaneGeometry(8.1,4.55),material,group,0,0,-.3);rear.rotation.y=Math.PI;for(const x of[-7,7])batch.add(.16,6,.16,x,46,z,steel);}
 const live=canvasTexture(1536,864,()=>{});let last='';
 return{setMatchday(on){material.map=textures[on?1:0];last='';},setMatchScore(state){const club=state.fixture;if(!club)return;const seconds=Math.max(0,Math.ceil(state.duration-state.elapsed)),clock=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0'),key=[club.id,state.score.home,state.score.away,clock].join(':');if(key===last)return;last=key;const c=live.image.getContext('2d');c.fillStyle='#101b25';c.fillRect(0,0,1536,864);c.fillStyle='#b01d35';c.fillRect(0,0,1536,18);c.textAlign='center';c.fillStyle='#b7c4c8';c.font='500 32px Arial';c.fillText('EXHIBITION · '+clock,768,110);c.drawImage(getCrestImage('home'),190,205,205,205);
  if(club.id==='dortmund')c.drawImage(getCrestImage('away'),1140,205,205,205);else{c.fillStyle=club.kit.shirt;c.beginPath();c.arc(1240,307,105,0,Math.PI*2);c.fill();c.fillStyle=club.kit.ink;c.font='bold 75px Arial';c.fillText(club.code,1240,335);}
  c.fillStyle='#f3f1e9';c.font='600 60px Arial';c.fillText('FC BAYERN',292,510);c.fillText(club.code,1240,510);c.font='600 180px Arial';c.fillText(state.score.home+' : '+state.score.away,768,405);c.font='400 34px Arial';c.fillStyle='#aab9bd';c.fillText('11  vs  11',768,520);c.fillText('FC BAYERN × '+club.english,768,740);live.needsUpdate=true;material.map=live;
 }};
}
